def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    args = [str(a) for a in varargs]
    if color:
        args = [f"{a}\033[1;32m" for a in args]
    cmd_str = " ".join(args)
    return _run_command(cmd_str, target_concurrency, _max_length, **kwargs)

def _run_command(cmd_str: str, target_concurrency: int, _max_length: int, **kwargs: Any) -> tuple[int, bytes]:
    parts = cmd_str.split()
    partitions = partition(parts, target_concurrency)
    results = [run(cmd_str[p], **kwargs) for p in partitions]
    exit_codes = [r[0] for r in results]
    return (max(exit_codes), b"".join(r[1] for r in results[1:]))

def partition(lst, n):
    size = len(lst) // n
    return [lst[i * size:(i + 1) * size] for i in range(n)]

