def extostr(e, max_level=30, max_path_level=5):
    if not isinstance(e, Exception):
        raise ValueError("'e' argument must be an exception instance")
    if not isinstance(max_level, int):
        raise ValueError("'max_level' argument must be an integer")
    if not isinstance(max_path_level, int):
        raise ValueError("'max_path_level' argument must be an integer")
    levels = ''
    level = 0
    while e and level < max_level:
        if hasattr(e, '__traceback__'):
            tb = e.__traceback__
            path = tb.tb_frame.f_code.co_filename
            line = tb.tb_lineno
            method = tb.tb_frame.f_code.co_name
            levels += f"Level {level}: {method}() in {path}:{line}\n"
        else:
            levels += f"There is no call stack!!"
            break
        e = e.__context__
        level += 1
    if level == max_level:
        levels += f"Level {level}: ..."
    return levels

