        raise ValueError("classes cannot be empty")

    ordered_classes = sorted(classes, key=lambda x: (x.name, x.abstractness))
    minimal_classes = []

    for cls in ordered_classes:
        if not any(issubclass(cls, base) for base in minimal_classes):
