                scale_schema = {"spec": {"completions": "integer"}}
            else:
                continue

            default_observer_schema[scale_name] = scale_schema

        return default_observer_schema
    except ValueError as e:
        raise KrakeCustomException(f"Failed to generate default observer schema: {e}")

