        if file_extension == '.xml':
            tree = ET.parse(file_path)
            root = tree.getroot()
            for asset in root.findall('asset'):
                for rendition in asset.findall('rendition'):
                    if rendition.attrib['type'] == 'image':
                        return {'type': 'image', 'file_path': file_path}
