def absorb(self, args: Sequence[str]):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption:

    A & (A | B) = A, A | (A & B) = A

    Negative absorption:

    A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        try:
            if arg in ("A", "~A", "B") and arg[-1] != "+":
                neg_arg = "~" + arg
                if neg_arg in args:
                    result.append(arg)
                    if neg_arg in ("A", "B"):
                        result.append(neg_arg)
        except IndexError:
            result.append(arg)
    return result

def absorb(self, args):
    # Check if args is a sequence of expressions
    if not isinstance(args, collections.Sequence):
        raise TypeError("args must be a sequence of expressions")

    # Initialize the result list
    result = []

    # Iterate over the args and apply absorption and negative absorption
    for arg in args:
        # Check if the arg is a supported expression
        if isinstance(arg, bool):
            # If the arg is a boolean value, simply add it to the result list
            result.append(arg)
        elif isinstance(arg, Number):
            # If the arg is a number, check if it is zero
            if arg == 0:
                # Add the boolean value False to the result list
                result.append(False)
            else:
                # Add the boolean value True to the result list
                result.append(True)
        elif isinstance(arg, str):
            # If the arg is a string, check if it represents a boolean value
            if arg.lower() == "false":
                # Add the boolean value False to the result list
                result.append(False)
            elif arg.lower() == "true":
                # Add the boolean value True to the result list
                result.append(True)
            else:
                # If the arg is not a supported expression, raise an error
                raise ValueError("Unsupported expression: " + arg)

    # Return the resulting list of boolean values
    return result

