def _fromutc(self, dt):
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime.datetime object")
    if dt.tzinfo is None:
        raise ValueError("dt must be a timezone-aware datetime object")
    new_tz = self.timezone
    if new_tz is None:
        raise ValueError("Timezone must not be None")
    if new_tz == dt.tzinfo:
        return dt
    new_dt = dt.astimezone(new_tz)
    if new_dt.utcoffset() == dt.utcoffset() and new_dt.dst() == dt.dst():
        return new_dt
    else:
        raise AmbiguousTimezoneError("The specified datetime is ambiguous in the target timezone")

