    """
    Call the given command(s).

    :param commands: A list of commands to run.
    :param args: A list of arguments to pass to each command.
    :param cwd: The working directory to use for each command.
    :param verbose: Whether to display verbose output.
    :param hide_stderr: Whether to hide stderr output.
    :param env: The environment to use for each command.
    :return: The return code of the last command, or a list of return codes if multiple commands were run.
    """
    try:
        if not isinstance(commands, list):
            commands = [commands]
        if not isinstance(args, list):
            args = [args]
        if cwd is None:
            cwd = os.getcwd()
        if env is None:
            env = os.environ.copy()
        return_codes = []
        for command in commands:
            process = subprocess.Popen(command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            stdout, stderr = process.communicate()
            if not hide_stderr:
                sys.stdout.write(stdout.decode())
            if process.returncode != 0:
                if verbose:
                    print("Error:", stderr.decode())
                return_codes.append(process.returncode)
        if len(return_codes) == 1:
            return return_codes[0]
        return return_codes
    except Exception as e:
        print("Error:", e)
        return -1

