def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        major, minor = version.split('.')
        minor = str(int(minor) + 1)
        if len(minor) < 2:
            minor = '0' + minor
        return major + '.' + minor
    except ValueError:
        raise ValueError("Invalid version format") from None

def next_version(version: str) -> str:
    """
    Returns the next version identifier following the existing pattern.

    Handles both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return "1.0.0"
    try:
        major, minor, patch = map(int, version.split("."))
        patch += 1
        return f"{major}.{minor}.{patch}"
    except ValueError:
        return "1.0.0"

