        if path_inventory.is_file():
            inventory_data = json.loads(path_inventory.read_text())
            if 'id' in inventory_data and inventory_data['id'] == path.name:
                return 'object'
            elif 'inventory' in inventory_data and inventory_data['inventory'] == path.name:
                return 'root'
            else:
                return 'file'
        else:
            return 'file'
    except (FileNotFoundError, json.JSONDecodeError):
        return 'error: unable to read inventory or invalid JSON'
    except TypeError:
        return 'error: invalid path provided'
