        return 'error: unexpected error occurred'

def find_path_type(path):
    # Check if the path is a directory
    if not os.path.isdir(path):
        return 'file'

    # Check for the "0=*" Namaste file
    for file in os.listdir(path):
        if file.startswith('0=') and file.endswith('*'):
            # Check if the file is an inventory file
            with open(os.path.join(path, file), 'rt') as inventory_file:
                try:
                    inventory = json.load(inventory_file)
                    if 'id' in inventory and 'versions' in inventory and 'main' in inventory['versions']:
                        return 'root'
                except ValueError:
                    pass

    # Check if the directory contains a version directory
    for file in os.listdir(path):
        if os.path.isdir(os.path.join(path, file)):
            version_dir_name = os.path.basename(file)
            if version_dir_name.startswith('v') and version_dir_name[1:].isdigit():
                return 'object'

    return 'other'

