    key_to_idx = {}
    for i, (key, value) in enumerate(nodes):
        if isinstance(value, MappingNode):
            if key not in key_to_idx:
                key_to_idx[key] = []
            key_to_idx[key].append(i)

    for key, idxs in key_to_idx.items():
