def _deep_merge_nodes(nodes_to_merge, key):
    result = {}
    for i, (key_i, value_i) in enumerate(nodes_to_merge):
        if key_i == key:
            if isinstance(value_i, MappingNode):
                result.update(_iter_deep_merge_nodes(nodes_to_merge, i))
            else:
                result[key_i] = value_i

    return result

def _iter_deep_merge_nodes(nodes_to_merge, i):
    nodes = nodes_to_merge[i]
    for key, value in nodes.items():
        if isinstance(value, MappingNode):
            yield key, _deep_merge_nodes(nodes_to_merge, key)
        else:
            yield key, value

def deep_merge_nodes(nodes):
    """
    Deep merge a list of tuples of ScalarNode and MappingNode objects.

    Args:
        nodes (list): A list of tuples in the form of (ScalarNode, MappingNode)

    Returns:
        list: A list of merged ScalarNode and MappingNode objects
    """
    merged_nodes = []
    for node in nodes:
        if isinstance(node, ScalarNode):
            merged_nodes.append(node)
        elif isinstance(node, MappingNode):
            existing_node = next((n for n in merged_nodes if n[0].value == node[0].value), None)
            if existing_node:
                existing_node[1].value.update(node[1].value)
            else:
                merged_nodes.append(node)
        else:
            raise TypeError(f"Invalid node type: {type(node)}")
    return merged_nodes
