        elif char == "M":
            return int(num) * 1000000
        elif char == "G":
            return int(num) * 1000000000
        elif char == "T":
            return int(num) * 1000000000000
        else:
            raise ValueError(f"unknown unit {char} in size string")

    return int(num)

