    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise TypeError("The input string must be a string.")
    if not isinstance(alphabet, list):
        raise TypeError("The alphabet must be a list of strings.")
    if not all(isinstance(char, str) for char in alphabet):
        raise TypeError("The alphabet must contain only strings.")
    if not len(alphabet) == len(set(alphabet)):
        raise ValueError("The alphabet must not contain duplicates.")

    base = len(alphabet)
    num = 0
    for i, char in enumerate(reversed(string)):
        if char not in alphabet:
            raise ValueError("The input string contains invalid characters.")
        num += alphabet.index(char) * (base ** i)

    return num

