    Find the roots in some sort of transitive hierarchy.

    Parameters:
        graph (rdflib.Graph): The RDF graph to search.
        prop (rdflib.URIRef): The property to use for the transitive hierarchy.
        roots (set, optional): The set of roots to search. Defaults to None.

    Returns:
        set: A set of nodes that are roots of the transitive hierarchy.
    """
    if roots is None:
        roots = set()

    for subj, pred, obj in graph.triples((None, prop, None)):
        if obj not in graph:
            continue
        if subj not in roots:
            roots.add(subj)
        if obj not in roots:
            roots.add(obj)

    return roots

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if not roots:
        roots = set()
    for triple in graph:
        if triple[1] == prop:
            roots.add(triple[0])
            roots = find_roots(graph, prop, roots)
    return roots

