def from_ticks(cls, ticks, tz=None):
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks out of bounds (0 <= ticks < 86400000000000)")
    return cls(hour=ticks // 3600000000000,
               minute=(ticks // 60000000000) % 60,
               second=(ticks // 1000000000) % 60,
               microsecond=ticks % 1000000000,
               tzinfo=tz)

def protocol_handlers(protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers, keyed by version tuple. If an explicit protocol version is provided, the dictionary will contain either zero or one items, depending on whether that version is supported. If no protocol version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed as a tuple")
        version_handler = {protocol_version: BoltProtocolHandler(protocol_version)}
    else:
        version_handler = {(3, 5): BoltProtocolHandler((3, 5))}
    return version_handler

def protocol_handlers(cls, protocol_version=None):
    if protocol_version is None:
        return {version: cls.protocol_handlers(version) for version in cls.supported_protocol_versions}
    if not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be passed in a tuple")
    if protocol_version not in cls.supported_protocol_versions:
        raise ValueError(f"Unsupported protocol version {protocol_version}")
    return {protocol_version: cls._get_protocol_handler(protocol_version)}

def protocol_handlers(cls, protocol_version=None):
    if protocol_version is None:
        return {version: cls.handlers[version] for version in cls.handlers}
    elif not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be passed as a tuple")
    else:
        version = protocol_version
        if version in cls.handlers:
            return {version: cls.handlers[version]}
        else:
            raise ValueError(f"Protocol version {version} is not supported")

