def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    # Ensure that hist contains only numeric bins
    if any(not is_numeric(bin.value) for bin in hist.bins):
        raise ValueError("All histogram bins must be numeric!")

    # Set default make_value function if not provided
    if make_value is None:
        make_value = lambda bin_: bin_.value
    elif not callable(make_value):
        raise ValueError("make_value must be a callable!")

    # Set default get_coordinate to "left"
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("Invalid get_coordinate!")

    # Ensure that field_names has the same number of elements as the result dimension
    if len(field_names) != hist.dimension:
        raise ValueError("Number of field names must match histogram dimension!")

    # Create the graph
    graph = cls.from_data(hist.bins, make_value, get_coordinate, field_names, scale)

    # Set the graph's scale
    if scale and not isinstance(scale, Scale):
        scale = Scale.from_histogram(hist)
    graph.scale = scale

    return graph

