    """Convert a histogram to a graph."""
    if make_value is None:
        make_value = lambda bin_: bin_
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("invalid get_coordinate value")
    if not len(field_names) == 2:
        raise ValueError("field_names must have 2 elements")
    if scale and not hist.scale:
        raise ValueError("scale is unknown for the histogram")
    x, y = field_names
    graph = Graph(x, y, scale=scale or hist.scale)
    for bin_ in hist:
        value = make_value(bin_)
        graph.add_point(getattr(bin_, get_coordinate), value)
    return graph

