    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"Object {candidate} does not claim to provide {iface}")

    provided_attributes, provided_methods = zip(*(iface.names(all=True)))
    implemented_attributes, implemented_methods = zip(*(candidate.names(all=True)))

    missing_attributes = set(provided_attributes) - set(implemented_attributes)
    missing_methods = set(provided_methods) - set(implemented_methods)

    errors = []

    for attribute in missing_attributes:
        errors.append(f"Object {candidate} is missing attribute {attribute}")

    for method in missing_methods:
        errors.append(f"Object {candidate} is missing method {method}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid(errors)

    return True

