def isoparse(self, dt_str):
    """
    Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    :param dt_str: A string or stream containing only an ISO-8601 datetime string
    :return: Returns a :class:`datetime.datetime` representing the string. Unspecified components default to their lowest value.
    """
    dt_str = dt_str.strip()
    match = ISO_8601_REGEX.fullmatch(dt_str)
    if match:
        date_parts = match.groupdict()
        try:
            date_parts = {k: int(v) for k, v in date_parts.items() if v is not None}
        except ValueError:
            raise ISO8601Error("Invalid date component")
        if "week" in date_parts:
            year, week, day = date_parts.values()
            return datetime.date(year, 1, 1) + datetime.timedelta(weeks=week - 1, days=day - 1)
        else:
            year, month, day = date_parts.values()
            return datetime.datetime(year, month, day)
    raise ISO8601Error("Invalid ISO-8601 string")

