def verify_relayable_signature(public_key, doc, signature):
    try:
        from cryptography.hazmat.primitives import hashes
        from cryptography.hazmat.primitives.asymmetric import padding
        from cryptography.exceptions import InvalidSignature
    except ImportError:
        print("Cryptography library is required for this function")
        return False

    # Parse the XML document and extract the signature
    try:
        xml_doc = ET.fromstring(str.encode(doc))
        signature_elem = xml_doc.find(".//ds:SignatureValue")
        if signature_elem is None:
            raise ValueError("Signature not found")
        signature_value = signature_elem.text.decode()
    except (ET.ParseError, UnicodeEncodeError, UnicodeDecodeError):
        raise ValueError("Invalid XML document")

    # Verify the signature using the public key
    try:
        verifier = padding.PKCS1v15()
        digest = hashes.SHA256().new(signature)
        verifier.verify(public_key, signature_value, digest)
    except InvalidSignature:
        return False

    return True

