def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Handle JSON format
    if document.startswith('{'):
        try:
            data = json.loads(document)
            # Extract relevant information
            user = data.get('nickname')
            server = data.get('server')
            if user and server:
                return {'user': user, 'server': server}
            else:
                raise ValueError('User or server information not found in JSON format')
        except json.JSONDecodeError:
            raise ValueError('Invalid JSON format')
    # Handle XRD format
    else:
        try:
            root = ET.fromstring(document)
            # Extract relevant information
            user = root.find('{http://docs.oasis-open.org/ns/liberty/xrd/v1.0}Account')
            server = root.find('{http://docs.oasis-open.org/ns/liberty/xrd/v1.0}ProviderID')
            if user and server:
                return {'user': user.text, 'server': server.text}
            else:
                raise ValueError('User or server information not found in XRD format')
        except ET.ParseError:
            raise ValueError('Invalid XRD format')

