def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    if not isinstance(settings_dirs, list):
        raise ValueError("settings_dirs must be a list")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string")
    if spec_option not in ["GLOBAL", "LOCAL"]:
        raise ValueError(f"Invalid spec_option: {spec_option}")

    ini_type = IniComplexType(settings_dirs)
    if spec_option == "GLOBAL":
        ini_type.add_global_file(settings_dirs)
    else:
        ini_type.add_local_file(settings_dirs)
    return ini_type.get_file_names()

