    Raises:
        ValueError: If an argument has no default value and is not provided.
        TypeError: If an argument is not of the expected type.
    """
    spec_defaults = {}
    for arg_name, arg_spec in self.arguments.items():
        if arg_spec.default is not None:
            spec_defaults[arg_name] = arg_spec.default
        else:
            if arg_name in self.arguments:
                arg_value = self.arguments[arg_name]
                if arg_spec.type is not None and not isinstance(arg_value, arg_spec.type):
                    raise TypeError(f"'{arg_name}' must be of type {arg_spec.type}.")
                spec_defaults[arg_name] = arg_value
            else:
