def merge_extra_vars(vars_dict, extra_vars=None):
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not isinstance(extra_vars, list) and extra_vars is not None:
        raise TypeError("extra_vars must be a list or None")
    if extra_vars is None:
        return vars_dict
    for var in extra_vars:
        if not isinstance(var, dict):
            raise TypeError("elements in extra_vars must be dictionaries")
        for key, value in var.items():
            if key in vars_dict and vars_dict[key] != value:
                raise ValueError(f"variable '{key}' has conflicting values: {vars_dict[key]} and {value}")
            vars_dict[key] = value
    return vars_dict

