    for var_name, var_value in extra_vars.items():
        if var_name in vars_dict and vars_dict[var_name] != var_value:
            raise ValueError(f"Conflicting values for {var_name}: {vars_dict[var_name]} and {var_value}")
        else:
            vars_dict[var_name] = var_value

    return vars_dict

def merge_extra_vars(vars_dict: dict, extra_vars: list) -> list:
    """Extend `vars_dict` with `extra-vars`

    Args:
        vars_dict (dict): Dictionary to merge extra-vars into
        extra_vars (list): List of extra-vars

    Returns:
        list: The merged list of vars
    """
    try:
        if extra_vars:
            vars_dict.update(dict(zip(extra_vars[::2], extra_vars[1::2])))
        return list(vars_dict.items())
    except TypeError:
        raise ValueError("Invalid type for `extra_vars`, expected a list of key-value pairs") from None

