def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict"""
    try:
        if not cli_args:
            raise ValueError("cli_args cannot be empty")
        elif not vars_dict:
            raise ValueError("vars_dict cannot be empty")
        else:
            ansible_cmd = "ansible"
            ansible_cmd += " -i %s" % ir_workspace.hosts_file
            ansible_cmd += " -u %s" % ir_workspace.username
            ansible_cmd += " --private-key %s" % ir_workspace.private_key_file
            ansible_cmd += " -e %s" % json.dumps(vars_dict)
            for arg in cli_args:
                ansible_cmd += " " + arg
            subprocess.check_output(ansible_cmd, shell=True, stderr=subprocess.STDOUT)
            return vars_dict
    except subprocess.CalledProcessError as e:
        raise e
    except ValueError as e:
        raise e


